public static IEnumerable<SqlDataRecord> ToSqlDataRecords(IEnumerable<ProfileFilter> filters)
{
    var metaData = new[]
    {
        new SqlMetaData("FilterTypeId", SqlDbType.Int),
        new SqlMetaData("Value", SqlDbType.VarChar, 100)
    };

    foreach (var filter in filters)
    {
        var record = new SqlDataRecord(metaData);
        record.SetInt32(0, filter.FilterTypeId);
        record.SetString(1, filter.Value);
        yield return record;
    }
}
