private sealed class EnumHandler : ITypeHandler
{
    public object Parse(Type destinationType, object value)
    {
        // Return null if the underlying value is null
        if (value == null || value is DBNull)
        {
            return null;
        }

        // Return the value if it is already the appropriate enumerated type
        if (value.GetType() == destinationType)
        {
            return value;
        }

        // Convert the integral value to the requested type
        return Enum.ToObject(destinationType, value);
    }

    public void SetValue(IDbDataParameter parameter, object value)
    {
        // Return object if the value is null
        if (value == null || value is DBNull)
        {
            parameter.Value = DBNull.Value;
            parameter.DbType = DbType.Object;
            return;
        }

        // This should never happen, but check to be sure
        var valueType = value.GetType();
        if (!(value is Enum))
        {
            throw new ArgumentException(string.Format(
                "{0} is not an enumerated type", valueType), "value");
        }

        // Get the type code of the underlying type
        var underlyingType = Enum.GetUnderlyingType(valueType);
        var typeCode = ((IConvertible)value).GetTypeCode();

        // Set the parameter to be the value cast to the underlying type
        switch (typeCode)
        {
            case TypeCode.Byte:
                parameter.Value = (byte)value;
                break;
            case TypeCode.SByte:
                parameter.Value = (sbyte)value;
                break;
            case TypeCode.Int16:
                parameter.Value = (short)value;
                break;
            case TypeCode.Int32:
                parameter.Value = (int)value;
                break;
            case TypeCode.Int64:
                parameter.Value = (long)value;
                break;
            case TypeCode.UInt16:
                parameter.Value = (ushort)value;
                break;
            case TypeCode.UInt32:
                parameter.Value = (uint)value;
                break;
            case TypeCode.UInt64:
                parameter.Value = (ulong)value;
                break;
            default:
                throw new InvalidEnumArgumentException(string.Format(
                    "The enumeration {0} has the unsupported underlying type code {1}",
                    valueType.FullName, typeCode));
        }

        // Set the parameter DbType
        parameter.DbType = typeMap[underlyingType];
    }
}

